// SEO Mission 2, part D: the sourced line-up of each Which member are you page.
//
// rosters.json is generated by scripts/fetch-wma-rosters.mjs (read only, rerun to
// refresh; never edited by hand). A member is in it only when Wikidata and the Members
// section of the group's English Wikipedia article both list them as current
// (docs/seo/KPOP-SOURCES.md, two agreeing sources). The public role is the one on that
// Wikipedia line, which cites its own source; a member without one has none here.
// Nothing about age, body, family or private life is stored: birth dates are only read
// by the script to set `minors`.
//
// Pure, no Supabase import: shared by the page, the result route and the unit tests.

import data from './rosters.json';

export interface RosterMember {
  /** personality_profiles.member_slug, or null when the quiz has no profile for this member. */
  profile: string | null;
  /** Stage name, in the quiz's own spelling when the member has a profile. */
  name: string;
  /** The name on the Wikipedia line (audit only). */
  wikipediaName: string;
  /** Wikidata item of the member, fetched by the script. */
  wikidata: string;
  /** Public role as Wikipedia lists it ("Leader, rapper"), or null. */
  role: string | null;
  /** A team of the group (SEVENTEEN's Hip-hop, Vocal and Performance teams), or null. */
  team: string | null;
  /** The Wikipedia line carries a note on this member: the count is not printed. */
  note?: boolean;
}

export interface Roster {
  groupSlug: string;
  /** The day both sources were read (YYYY-MM-DD). */
  checkedOn: string;
  wikidataUrl: string;
  wikipediaUrl: string;
  /** The group's official site (Wikidata P856, answered when checked), or null. */
  official: string | null;
  /** Both sources list exactly these members and no line has a note: the count may be printed. */
  countAgreed: boolean;
  /** A member was under 18 (or had no known birth date) when checked: stage role only, no per-member stats. */
  minors: boolean;
  members: RosterMember[];
  /** Quiz profiles of members both sources list as former members. */
  formerProfiles: string[];
}

interface RawGroup {
  wikidata: string;
  wikipedia: { title: string; revid: number };
  official: string | null;
  countAgreed: boolean;
  minors: boolean;
  members: Array<{ profile: string | null; name: string; wikipediaName: string; wikidata: string; role: string | null; team: string | null; note?: boolean }>;
  former: Array<{ profile: string | null; name: string; wikidata: string }>;
}

const RAW = data as unknown as { checkedOn: string; groups: Record<string, RawGroup> };

const QID = /^Q[1-9]\d*$/;

export function wikidataUrl(qid: string): string {
  return `https://www.wikidata.org/wiki/${qid}`;
}

export function wikipediaUrl(title: string): string {
  return `https://en.wikipedia.org/wiki/${encodeURIComponent(title.replace(/ /g, '_'))}`;
}

/** The sourced line-up of a group, or null when the file has none (the members section then hides). */
export function getRoster(groupSlug: string): Roster | null {
  const g = Object.prototype.hasOwnProperty.call(RAW.groups, groupSlug) ? RAW.groups[groupSlug] : undefined;
  if (!g || !QID.test(g.wikidata) || g.members.length === 0) return null;
  return {
    groupSlug,
    checkedOn: RAW.checkedOn,
    wikidataUrl: wikidataUrl(g.wikidata),
    wikipediaUrl: `${wikipediaUrl(g.wikipedia.title)}#Members`,
    official: g.official,
    countAgreed: g.countAgreed,
    minors: g.minors,
    members: g.members.map((m) => ({ ...m })),
    formerProfiles: g.former.map((f) => f.profile).filter((p): p is string => typeof p === 'string'),
  };
}

/** Every group slug the file covers. */
export function rosterSlugs(): string[] {
  return Object.keys(RAW.groups).sort();
}

/**
 * The quiz profiles of current members: a profile both sources list as a former member
 * is left out, so the quiz never names a former member as a member of the group. A
 * profile the sources do not mention either way is kept (absence is not evidence).
 */
export function currentProfiles<T extends { id: string }>(groupSlug: string, profiles: readonly T[]): T[] {
  const former = new Set(getRoster(groupSlug)?.formerProfiles ?? []);
  return profiles.filter((p) => !former.has(p.id));
}

/** The sourced public role of a profile ("Rapper, hip-hop team"), or null. */
export function sourcedRole(groupSlug: string, profileId: string): string | null {
  const m = getRoster(groupSlug)?.members.find((x) => x.profile === profileId);
  if (!m || !m.role) return null;
  // The team only when the role does not already name it ("Vocal unit leader, ...").
  const team = m.team?.toLowerCase() ?? null;
  return team && !m.role.toLowerCase().includes(team.split(' ')[0]!) ? `${m.role}, ${team}` : m.role;
}
